function eb.weatherStrength(En)
local Fn=eb.fx(En)
local Gn=Fn.dmg/Fn.cd/Fn.hp/Fn.speed*(1+(Fn.range-1)/2)
for Hn,In in pairs(Fn.kinds)do
Gn=Gn*(1+Q.rogueShare(Hn)*In)
end
if Fn.ice>0 then
local Jn=Q.rogueShare(Wwc[1619])
Gn=Gn*(Jn+(1-Jn)/(1-Fn.ice+Fn.ice/W.modFactor(Wwc[1669])))
end
if Fn.fly>0 then
Gn=Gn*(1-Fn.fly*0.5)
end
if Fn.noCC then
Gn=Gn*0.95
end
if Fn.shroud then
Gn=Gn*0.9
end
return Gn
end
