vK=vK*xK/(xK+(tonumber(wK.max)or 0)*(tonumber(wK.late.dmg)or 0)*(tonumber(wK.hits)or 1)/math.max(0.1,tonumber(wK.late.cd)or 4))
end
lK=lK+vK
elseif tK.id==Wwc[2060]then
lK=lK+(tonumber(uK.dmg_buff)or 0)*0.25
elseif tK.id==Wwc[2061]then
lK=lK+(tonumber(uK.dmg_buff)or 0)*mK
elseif tK.id==Wwc[2062]then
