if WN>0 then
R.add(string.format(Wwc[2089],LN,DN.name),LN,Wwc[2090],string.format(Wwc[2091],M.fmt(WN),RN,db.level(VN)))
db.note(string.format(Wwc[2092],DN.name,LN,M.fmt(WN),RN,db.level(VN),math.abs(WN-KN)>KN*0.1 and string.format(Wwc[2093],M.fmt(KN))or Wwc[369]))
