function P.fuseFuel(fQ,gQ)
local hQ=H.session()
local iQ={[fQ.uuid]=true,[I.evolveUnit]=true,[I.fuseXpUnit]=true}
local jQ={}
for kQ,lQ in ipairs(N.equipped())do
iQ[lQ.uuid]=true
end
for mQ,nQ in ipairs(J.savedTeam or{})do
iQ[nQ]=true
end
for oQ,pQ in ipairs(J.train and J.train.on and J.train.on.base or{})do
iQ[pQ]=true
end
for qQ,rQ in ipairs(J.goals or{})do
iQ[rQ.uuid]=true
for sQ,tQ in ipairs(rQ.eats or{})do
jQ[tQ.id]=true
end
end
for uQ,vQ in ipairs(J.str and J.str.core or{})do
iQ[vQ]=true
end
local wQ=ab.strongest(10)
local xQ,yQ={},0
for zQ,AQ in pairs(hQ.profile_data.collection.owned_units)do
local BQ=hQ.collection:get_unit_by_uuid(zQ)or AQ
local CQ,DQ,EQ=pcall(H.USC.is_unit_good_for_fusion,fQ,BQ)
if CQ and DQ and not(AQ._locked or BQ._locked)and not iQ[zQ]and not jQ[BQ.unit_id]and not(AQ._equipped_relic or BQ._equipped_relic)and not(AQ.shiny or BQ.shiny)and not N.trait(BQ)and not(AQ.further_modifiers and AQ.further_modifiers.limit_break)then
local FQ=ab.fodderOrder(BQ.unit_id)
if FQ and not wQ[zQ]then
local GQ,HQ=pcall(N.score,BQ)
table.insert(xQ,{uuid=zQ,id=BQ.unit_id,pts=tonumber(EQ)or 1,sc=GQ and HQ or 0,order=FQ})
yQ=yQ+(tonumber(EQ)or 1)
end
end
end
table.sort(xQ,function(IQ,JQ)
if IQ.order~=JQ.order then
return IQ.order<JQ.order
end
if IQ.sc~=JQ.sc then
return IQ.sc<JQ.sc
end
return IQ.uuid<JQ.uuid
end)
local KQ,LQ={},0
for MQ,NQ in ipairs(xQ)do
