bR[fR.uuid]=true
end
local gR={}
for hR,iR in pairs(PQ.profile_data.collection.owned_units)do
if hR~=OQ.uuid and not QQ[hR]and not iR._locked then
local jR=PQ.collection:get_unit_by_uuid(hR)or iR
local kR,lR,mR=pcall(H.USC.is_unit_good_for_fusion,OQ,jR)
if kR and lR and not jR._locked then
local nR=H.Units[jR.unit_id]or{}
local oR={}
local pR,qR=N.trait(jR)
if pR then
table.insert(oR,Wwc[2168]..tostring((H.traitInfo(pR)or{}).name or pR)..(qR and qR~=Wwc[1578]and(Wwc[1584]..qR)or Wwc[369]))
end
if jR._equipped_relic or iR._equipped_relic then
