function Q.coverage(kGb,lGb)
local mGb={}
for nGb,oGb in ipairs(kGb)do
local pGb=oGb._stats
if not N.isFarm(pGb.id.Value)and pGb:FindFirstChild(Wwc[1577])then
table.insert(mGb,{p=M.flat(oGb:GetPivot().Position),r=pGb.range.Value*(N.SUMMONER[pGb.id.Value]and N.SUMMONER[pGb.id.Value].reach or 1),air=Q.canAir(oGb)})
end
end
local qGb,rGb=0,0
if#mGb>0 then
for sGb,tGb in ipairs(Q.samples)do
if tGb.prog>rGb then
local uGb=M.flat(tGb.pos)
for vGb,wGb in ipairs(mGb)do
if(uGb-wGb.p).Magnitude<=wGb.r then
if tGb.prog>qGb then
qGb=tGb.prog
end
if wGb.air then
rGb=tGb.prog
break
end
end
end
end
end
