local zGb={}
for AGb,BGb in ipairs(Q.samples)do
local CGb=M.flat(BGb.pos)
for DGb,EGb in ipairs(mGb)do
if(CGb-EGb.p).Magnitude<=EGb.r then
local FGb=tostring(BGb.lane)
zGb[FGb]=(zGb[FGb]or 0)+1
if BGb.prog>(xGb[FGb]or 0)then
xGb[FGb]=BGb.prog
end
break
end
end
