Q.laneW[KGb]=(yGb.avg/math.max(1,LGb))*(1+1.5*(HGb>0 and(1-GGb[KGb]/HGb)or 0))
end
Q.laneFrac=GGb
else
Q.laneW,Q.laneFrac=nil,nil
end
local MGb,NGb,OGb
