for PGb,QGb in ipairs(lGb)do
local RGb=(Q.laneW and QGb.lane and xGb[QGb.lane])or qGb
if QGb.hp>0 and QGb.prog>RGb+0.02 and QGb.prog>(MGb or 0)then
MGb,OGb=QGb.prog,Q.laneW and QGb.lane or nil
