NGb=true
end
end
end
local SGb= #mGb>0 and(Q.pressure or 0)>=qGb-0.08
return{covEnd=qGb,airEnd=rGb,leak=MGb,leakLane=OGb,covL=xGb,airLeak=NGb,push=SGb,units= #mGb}
end
