table.insert(Q.trialTrace,string.format(Wwc[2963],HQb,GQb-(Q.startT or GQb),IQb,table.concat(KQb,Wwc[2053]),MQb,LQb+SQb,#(Q.enemies or{}),Q.hpAliveRaw or 0,Q.waveMax[HQb-1]or 0,Q.teamDps or 0))
