local XQb=0
for YQb,ZQb in ipairs(Q.incomeLog)do
XQb=XQb+ZQb.y
end
local _Qb=math.min(30,GQb-(Q.startT or GQb))
Q.incomeRate=_Qb>=8 and XQb/_Qb or nil
