for EUb,FUb in ipairs(Q.mine or{})do
local GUb=FUb._stats
local HUb=N.rows(GUb.id.Value)
local IUb=HUb and HUb[math.min(GUb.upgrade.Value,HUb.max)]
local JUb=IUb and IUb.atk and N.attackInfo(IUb.atk,IUb.range)
if JUb and((JUb.stun or 0)>0 or(JUb.slowTime or 0)>0)then
DUb=DUb+1
end
end
local KUb,LUb=W.mask(Q.info.map,N.range(AUb.u,0)*(Q.info.rangeScale or 1)),0
for MUb=1,W.BINS do
if KUb[MUb]then
LUb=LUb+1
end
end
local NUb=Q.depth and Q.depth.units>0 and Q.depth.covEnd or 1
local OUb=(N.airFrom(AUb.id)==0)and 1 or(1-(1-H.FLY_GROUND)*math.min(1,Q.info.flyChance or 0))
