local UUb,VUb=pcall(N.range,PUb.u,0)
VUb=(UUb and tonumber(VUb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local WUb=0
for XUb,YUb in ipairs(RUb)do
local ZUb=0
for _Ub,aVb in ipairs(RUb)do
if(aVb.pos-YUb.pos).Magnitude<=VUb then
local bVb=QUb.types[aVb.base]
local cVb=bVb*QUb.uptime
if TUb then
cVb=math.max(0,math.min(TUb,(aVb.n+1)*bVb*QUb.uptime)-math.min(TUb,aVb.n*bVb*QUb.uptime))
